amount = contract.get_advantage_amount_by_code('MEAL')
paid_days = 0.0
total_days = 0.0

for line in worked_days.values():
    total_days += line.number_of_days or 0.0
    if line.is_paid:
        paid_days += line.number_of_days or 0.0

if total_days > 0:
    result = amount * paid_days / total_days
else:
    result = 0.0

